css:
#nat-cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  width: 100%;
  background-color: #ffffff;
  box-shadow: 0 -4px 15px rgba(0,0,0,0.1);
  z-index: 99999;
  transform: translateY(100%);
  transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
  padding: 1.2rem;
  border-top: 3px solid var(--nat-primary, #8FBC8F);
  display: none;
}
#nat-cookie-banner.is-ready { display: block; }
#nat-cookie-banner.show-banner { transform: translateY(0); }
#nat-cookie-banner .cookie-wrapper {
  max-width: 1140px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}
@media (min-width: 768px) {
  #nat-cookie-banner .cookie-wrapper { flex-direction: row; }
}
#nat-cookie-banner p {
  margin: 0;
  color: var(--nat-text, #333);
  font-size: 0.95rem;
  text-align: center;
  line-height: 1.5;
}
#nat-cookie-banner a { color: var(--nat-primary, #8FBC8F); font-weight: 700; text-decoration: none; }
#nat-cookie-btn {
  background-color: var(--nat-primary, #8FBC8F);
  color: #121212;
  border: none;
  padding: 10px 30px;
  border-radius: 50px;
  font-weight: 700;
  font-size: 0.95rem;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  transition: all 0.3s ease;
  white-space: nowrap;
}
#nat-cookie-btn:hover { background-color: #222222; color: #ffffff; }

javascript:
(function() {
  document.addEventListener('DOMContentLoaded', function() {
    var banner = document.getElementById('nat-cookie-banner');
    var btn = document.getElementById('nat-cookie-btn');

    if (!localStorage.getItem('nat_cookie_consent_v1')) {
      banner.classList.add('is-ready');
      setTimeout(function() {
        banner.classList.add('show-banner');
      }, 800);
    }

    btn.addEventListener('click', function() {
      localStorage.setItem('nat_cookie_consent_v1', 'true');
      banner.classList.remove('show-banner');
      setTimeout(function() {
        banner.classList.remove('is-ready');
      }, 600);
    });
  });
})();
